import test from 'node:test';
import assert from 'node:assert/strict';
import {issueForm,issuePayload,toggleLabel,mergeIssuePages,eligibleParents,relativeDue,issueListFilters} from '../src/pages/work/issue-state.js';
test('issue form serializes persisted nullable values and labels for editing',()=>{
  const form=issueForm({title:'x',estimate:0,priority:2,labels:[{id:'l'}]});
  assert.equal(form.estimate,'0');assert.equal(form.priority,'2');assert.deepEqual(form.labelIds,['l']);assert.equal(form.parentId,'');
  const input=issuePayload(form);assert.equal(input.estimate,0);assert.equal(input.assigneeId,null);assert.deepEqual(input.labelIds,['l']);
});
test('label picker toggles without mutating original state',()=>{const selected=['a'];assert.deepEqual(toggleLabel(selected,'b'),['a','b']);assert.deepEqual(toggleLabel(selected,'a'),[]);assert.deepEqual(selected,['a']);});
test('load-more issue pages replace overlaps and preserve order',()=>{assert.deepEqual(mergeIssuePages([{id:'a',title:'old'},{id:'b'}],[{id:'a',title:'new'},{id:'c'}]),[{id:'a',title:'new'},{id:'b'},{id:'c'}]);});
test('parent choices exclude the current issue and all descendants',()=>{const issues=[{id:'a'},{id:'b',parentId:'a'},{id:'c',parentId:'b'},{id:'d'}];assert.deepEqual(eligibleParents(issues,'a').map(item=>item.id),['d']);});
test('due state distinguishes overdue today and future',()=>{assert.equal(relativeDue('2026-01-01','2026-01-02').overdue,true);assert.equal(relativeDue('2026-01-02','2026-01-02').label,'Due today');assert.equal(relativeDue(null).label,'No due date');});
test('issue filters preserve priority zero and discard empty controls',()=>{assert.deepEqual(issueListFilters({priority:'0',statusId:'',q:'ship'}),{priority:'0',q:'ship'});});
